import { expect, test } from "vitest";
import { alignLines, ddlLines, lineKey } from "./align";

const SOURCE = [
  "CREATE TABLE billing.invoices (",
  "  id bigint GENERATED BY DEFAULT AS IDENTITY,",
  "  total numeric(12,2) NOT NULL DEFAULT 0,",
  "  due_on date,",
  "  CONSTRAINT invoices_pkey PRIMARY KEY (id)",
  ");",
  "CREATE INDEX invoices_due_on_idx ON billing.invoices (due_on);",
];
const TARGET = [
  "CREATE TABLE billing.invoices (",
  "  id bigint GENERATED BY DEFAULT AS IDENTITY,",
  "  total numeric(10,2) NOT NULL DEFAULT 0,",
  "  fax text,",
  "  CONSTRAINT invoices_pkey PRIMARY KEY (id)",
  ");",
];

test("lines_align_with_fillers_and_marks", () => {
  const rows = alignLines(SOURCE, TARGET);
  expect(rows.map((r) => r.mark)).toEqual(["same", "same", "changed", "added", "removed", "same", "same", "added"]);
  // A changed row pairs the two total lines.
  expect(rows[2].left?.text).toContain("numeric(12,2)");
  expect(rows[2].right?.text).toContain("numeric(10,2)");
  // Source-only due_on has a filler on the target side; target-only fax a filler on the source side.
  expect(rows[3]).toMatchObject({ left: { n: 4, text: "  due_on date," }, right: null });
  expect(rows[4]).toMatchObject({ left: null, right: { n: 4, text: "  fax text," } });
  // Each side numbers its own lines.
  expect(rows.map((r) => r.left?.n ?? null)).toEqual([1, 2, 3, 4, null, 5, 6, 7]);
  expect(rows.map((r) => r.right?.n ?? null)).toEqual([1, 2, 3, null, 4, 5, 6, null]);
  // Both panes get the same row count.
  expect(rows.length).toBe(8);
});

test("a_missing_side_is_all_fillers", () => {
  expect(alignLines(["CREATE TABLE r (", ");"], []).map((r) => [r.mark, r.right])).toEqual([
    ["added", null],
    ["added", null],
  ]);
  expect(alignLines([], ["x"]).map((r) => r.mark)).toEqual(["removed"]);
});

test("enum_values_pair_by_value", () => {
  const rows = alignLines(["  'void',", "  'written_off'", ");"], ["  'void'", ");"]);
  expect(rows.map((r) => r.mark)).toEqual(["changed", "added", "same"]);
});

test("line_key_and_ddl_lines", () => {
  expect(lineKey('  "total" numeric,')).toBe("total");
  expect(lineKey("  'void',")).toBe("void");
  expect(ddlLines(null)).toEqual([]);
  expect(ddlLines("a\r\nb\n")).toEqual(["a", "b"]);
});

test("an_added_index_next_to_a_removed_one_is_two_rows", () => {
  const rows = alignLines(["CREATE INDEX invoices_due_on_idx ON billing.invoices (due_on);"], ["CREATE INDEX invoices_fax_idx ON billing.invoices (fax);"]);
  expect(rows.map((r) => r.mark)).toEqual(["added", "removed"]);
  expect(lineKey("CREATE UNIQUE INDEX a_idx ON t (x);")).toBe("index a_idx");
  expect(lineKey("  CONSTRAINT invoices_pkey PRIMARY KEY (id)")).toBe("constraint invoices_pkey");
});

test("crossing_pairs_keep_both_sides_in_order", () => {
  const rows = alignLines(["  a int,", "  b int,"], ["  b text,", "  a text,"]);
  expect(rows.map((r) => r.right?.n ?? null).filter((n) => n !== null)).toEqual([1, 2]);
  expect(rows.map((r) => r.left?.n ?? null).filter((n) => n !== null)).toEqual([1, 2]);
});
